using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;
using Xunit;

namespace Sace.Api.Tests;

public class Sprint6ReportTests {
  [Fact]
  public async Task Immex_seed_is_idempotent_and_preserves_risk_v1(){using var factory=new SaceFactory();_ =factory.CreateClient();await DbSeeder.SeedAsync(factory.Services);await DbSeeder.SeedAsync(factory.Services);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();Assert.Equal(8,await db.Annex24CoverageItems.CountAsync());Assert.Equal(4,await db.Annex24CoverageItems.CountAsync(x=>x.CoverageStatus==Annex24CoverageStatus.SUPPORTED));Assert.Equal(5,await db.ImmexTemporalityRules.CountAsync());Assert.Equal(4,await db.OfficialLegalSources.CountAsync(x=>x.Code=="SAT-RGCE-ANEXO24-2026"||x.Code=="SAT-RGCE-2026-CONTROL-INVENTARIOS"||x.Code=="LEY-ADUANERA-VIGENTE-2025-11-19"||x.Code=="DECRETO-IMMEX-COMPILADO"));Assert.Equal(10,await db.RiskProfiles.Where(x=>x.Code=="RISK-OPS-V1"&&x.Version==1).SelectMany(x=>x.Factors).CountAsync());Assert.Equal(8,await db.RiskProfiles.Where(x=>x.Code=="RISK-OPS-V2"&&x.Version==2).SelectMany(x=>x.Factors).CountAsync(x=>x.SourceType==RiskSourceType.IMMEX));}

  [Theory]
  [InlineData("entries")]
  [InlineData("exits")]
  [InlineData("balances")]
  [InlineData("material-usage")]
  public async Task Every_report_requires_jwt(string report){using var factory=new SaceFactory();var response=await factory.CreateClient().GetAsync($"/api/immex/reports/{report}");Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}

  [Fact]
  public async Task Entries_report_applies_period_and_returns_two_unique_rows(){using var factory=new SaceFactory();var client=await Authenticated(factory);var ids=await Base(factory);await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();db.ImmexInventoryEntries.AddRange(Entry(ids,"26-ENTRY-1",new(2026,1,5),100),Entry(ids,"26-ENTRY-2",new(2026,1,20),200),Entry(ids,"26-OUTSIDE",new(2025,12,31),300));await db.SaveChangesAsync();}using var json=await Json(await client.GetAsync($"/api/immex/reports/entries?programId={ids.ProgramId}&from=2026-01-01&to=2026-01-31"));var rows=json.RootElement.GetProperty("items").EnumerateArray().ToList();Assert.Equal(2,rows.Count);Assert.Equal(2,rows.Select(x=>x.GetProperty("pedimentoNumber").GetString()).Distinct().Count());Assert.All(rows,x=>{Assert.Equal("IN",x.GetProperty("pedimentoKey").GetString());Assert.Equal("MÁT-Á",x.GetProperty("material").GetString());Assert.Equal("85011010",x.GetProperty("tariffFraction").GetString());Assert.Equal("PZA",x.GetProperty("tigieUnit").GetString());Assert.True(x.GetProperty("originalQuantity").GetDecimal()>0);});Assert.DoesNotContain(rows,x=>x.GetProperty("pedimentoNumber").GetString()=="26-OUTSIDE");}

  [Fact]
  public async Task Exits_report_returns_return_transfer_and_regime_change_with_discharge_links(){using var factory=new SaceFactory();var client=await Authenticated(factory);var ids=await Base(factory);await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var entry=Entry(ids,"26-ENTRY-EXITS",new(2026,1,1),150);entry.AvailableQuantity=0;entry.Status=ImmexInventoryEntryStatus.DISCHARGED;var kinds=new[]{ImmexExitType.RETURN,ImmexExitType.TRANSFER,ImmexExitType.REGIME_CHANGE};for(var i=0;i<kinds.Length;i++){var exit=new ImmexInventoryExit{ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,ExitType=kinds[i],PedimentoNumber=$"26-EXIT-{i+1}",PedimentoKey="RT",ExitDate=new(2026,2,i+1),Quantity=50,AllocatedQuantity=50,Unit="PZA",DischargeOutcome=ImmexDischargeOutcome.ALLOCATED};exit.Discharges.Add(new(){InventoryEntry=entry,MaterialId=ids.MaterialId,Sequence=1,QuantityDischarged=50,Unit="PZA",EntryBalanceBefore=150-(i*50),EntryBalanceAfter=100-(i*50),Explanation="PEPS sintético"});db.ImmexInventoryExits.Add(exit);}await db.SaveChangesAsync();Assert.Equal(3,await db.ImmexInventoryDischarges.CountAsync(x=>x.InventoryEntryId==entry.Id));}using var json=await Json(await client.GetAsync($"/api/immex/reports/exits?programId={ids.ProgramId}&from=2026-02-01&to=2026-02-28"));var rows=json.RootElement.GetProperty("items").EnumerateArray().ToList();Assert.Equal(3,rows.Count);Assert.Equal(new[]{"REGIME_CHANGE","RETURN","TRANSFER"},rows.Select(x=>x.GetProperty("exitType").GetString()).Order().ToArray());Assert.All(rows,x=>{Assert.StartsWith("26-EXIT-",x.GetProperty("pedimentoNumber").GetString());Assert.Equal(50,x.GetProperty("quantity").GetDecimal());Assert.Equal("PZA",x.GetProperty("unit").GetString());Assert.Equal("ALLOCATED",x.GetProperty("dischargeOutcome").GetString());});}

  [Fact]
  public async Task Balance_report_does_not_duplicate_entry_with_two_discharge_lines(){using var factory=new SaceFactory();var client=await Authenticated(factory);var ids=await Base(factory);await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var entry=Entry(ids,"26-BALANCE",new(2026,3,1),1000);entry.AvailableQuantity=500;entry.Status=ImmexInventoryEntryStatus.PARTIALLY_DISCHARGED;var first=Exit(ids,"26-OUT-300",new(2026,3,5),300);first.Discharges.Add(Discharge(entry,ids.MaterialId,300,1000,700));var second=Exit(ids,"26-OUT-200",new(2026,3,6),200);second.Discharges.Add(Discharge(entry,ids.MaterialId,200,700,500));db.AddRange(first,second);await db.SaveChangesAsync();}using var json=await Json(await client.GetAsync($"/api/immex/reports/balances?programId={ids.ProgramId}&from=2026-03-01&to=2026-03-31"));var row=Assert.Single(json.RootElement.GetProperty("items").EnumerateArray());Assert.Equal(1000,row.GetProperty("original").GetDecimal());Assert.Equal(500,row.GetProperty("discharged").GetDecimal());Assert.Equal(500,row.GetProperty("available").GetDecimal());Assert.Equal(1,row.GetProperty("openPedimentos").GetInt32());}

  [Fact]
  public async Task Material_usage_report_keeps_used_loss_and_waste_separate(){using var factory=new SaceFactory();var client=await Authenticated(factory);var ids=await Base(factory);await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();db.ImmexMaterialUsages.AddRange(new(){ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,ProductId=ids.ProductId,PeriodStart=new(2026,4,1),PeriodEnd=new(2026,4,30),QuantityUsed=100,LossQuantity=10,WasteQuantity=5,Unit="PZA"},new(){ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,ProductId=ids.ProductId,PeriodStart=new(2026,5,1),PeriodEnd=new(2026,5,31),QuantityUsed=999,LossQuantity=99,WasteQuantity=9,Unit="PZA"});await db.SaveChangesAsync();}using var json=await Json(await client.GetAsync($"/api/immex/reports/material-usage?programId={ids.ProgramId}&from=2026-04-01&to=2026-04-30"));var row=Assert.Single(json.RootElement.GetProperty("items").EnumerateArray());Assert.Equal(100,row.GetProperty("quantityUsed").GetDecimal());Assert.Equal(10,row.GetProperty("lossQuantity").GetDecimal());Assert.Equal(5,row.GetProperty("wasteQuantity").GetDecimal());Assert.Equal("MÁT-Á",row.GetProperty("material").GetString());}

  [Theory]
  [InlineData("entries","PedimentoNumber","26-CSV-ENTRY")]
  [InlineData("exits","ExitType","RETURN")]
  [InlineData("balances","Original","100")]
  [InlineData("material-usage","QuantityUsed","100")]
  public async Task Csv_reports_are_utf8_quoted_filtered_and_keep_accents(string report,string expectedHeader,string expectedValue){using var factory=new SaceFactory();var client=await Authenticated(factory);var ids=await CsvScenario(factory);var response=await client.GetAsync($"/api/immex/reports/{report}?programId={ids.ProgramId}&from=2026-06-01&to=2026-06-30&format=csv");response.EnsureSuccessStatusCode();Assert.Equal("text/csv",response.Content.Headers.ContentType?.MediaType);Assert.Equal("utf-8",response.Content.Headers.ContentType?.CharSet);var bytes=await response.Content.ReadAsByteArrayAsync();Assert.True(bytes.AsSpan().StartsWith(Encoding.UTF8.GetPreamble()));var csv=Encoding.UTF8.GetString(bytes);Assert.Contains($"\"{expectedHeader}\"",csv);Assert.Contains($"\"{expectedValue}",csv);Assert.Contains("MÁT-Á",csv);Assert.DoesNotContain("FUERA-PERIODO",csv);Assert.All(csv.Split('\n',StringSplitOptions.RemoveEmptyEntries),line=>Assert.StartsWith("\"",line.TrimStart('\uFEFF')));}

  [Theory]
  [InlineData("entries")]
  [InlineData("exits")]
  [InlineData("balances")]
  [InlineData("material-usage")]
  public async Task Csv_empty_dataset_contains_only_header(string report){using var factory=new SaceFactory();var client=await Authenticated(factory);var response=await client.GetAsync($"/api/immex/reports/{report}?from=2035-01-01&to=2035-01-31&format=csv");response.EnsureSuccessStatusCode();var csv=await response.Content.ReadAsStringAsync();Assert.Single(csv.Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries));}

  static async Task<HttpClient> Authenticated(SaceFactory factory){var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});login.EnsureSuccessStatusCode();using var json=JsonDocument.Parse(await login.Content.ReadAsStringAsync());client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",json.RootElement.GetProperty("token").GetString());return client;}
  static async Task<JsonDocument> Json(HttpResponseMessage response){var body=await response.Content.ReadAsStringAsync();response.EnsureSuccessStatusCode();return JsonDocument.Parse(body);}
  static async Task<Ids> Base(SaceFactory factory){await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var program=new ImmexProgram{ProgramNumber=$"TEST-{Guid.NewGuid():N}",CompanyName="Empresa sintética",Rfc="AAA010101AAA",Status=ImmexProgramStatus.ACTIVE};var material=new ImmexMaterial{ImmexProgram=program,MaterialCode="MÁT-Á",Description="Material sintético con acento",TariffFraction="85011010",TigieUnit="PZA"};var product=new ImmexProduct{ImmexProgram=program,ProductCode="PROD-1",Description="Producto sintético",TariffFraction="85011010",TigieUnit="PZA"};db.AddRange(program,material,product);await db.SaveChangesAsync();return new(program.Id,material.Id,product.Id);}
  static async Task<Ids> CsvScenario(SaceFactory factory){var ids=await Base(factory);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();db.ImmexInventoryEntries.AddRange(Entry(ids,"26-CSV-ENTRY",new(2026,6,2),100),Entry(ids,"FUERA-PERIODO",new(2026,5,31),25));db.ImmexInventoryExits.AddRange(Exit(ids,"26-CSV-EXIT",new(2026,6,10),40),Exit(ids,"FUERA-PERIODO",new(2026,5,31),5));db.ImmexMaterialUsages.AddRange(new(){ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,ProductId=ids.ProductId,PeriodStart=new(2026,6,1),PeriodEnd=new(2026,6,30),QuantityUsed=100,LossQuantity=10,WasteQuantity=5,Unit="PZA"},new(){ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,PeriodStart=new(2026,5,1),PeriodEnd=new(2026,5,31),QuantityUsed=1,Unit="PZA"});await db.SaveChangesAsync();return ids;}
  static ImmexInventoryEntry Entry(Ids ids,string pedimento,DateTime date,decimal quantity)=>new(){ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,PedimentoNumber=pedimento,PedimentoKey="IN",PedimentoItemNumber=1,Sequence=1,EntryDate=date,TariffFraction="85011010",PartNumber="MÁT-Á",Description="Material sintético",OriginalQuantity=quantity,AvailableQuantity=quantity,TigieUnit="PZA",InventoryClassification=ImmexInventoryClassification.COMPONENT,Status=ImmexInventoryEntryStatus.OPEN};
  static ImmexInventoryExit Exit(Ids ids,string pedimento,DateTime date,decimal quantity)=>new(){ImmexProgramId=ids.ProgramId,MaterialId=ids.MaterialId,ExitType=ImmexExitType.RETURN,PedimentoNumber=pedimento,PedimentoKey="RT",ExitDate=date,Quantity=quantity,AllocatedQuantity=quantity,Unit="PZA",DischargeOutcome=ImmexDischargeOutcome.ALLOCATED};
  static ImmexInventoryDischarge Discharge(ImmexInventoryEntry entry,Guid materialId,decimal quantity,decimal before,decimal after)=>new(){InventoryEntry=entry,MaterialId=materialId,Sequence=1,QuantityDischarged=quantity,Unit="PZA",EntryBalanceBefore=before,EntryBalanceAfter=after,Explanation="PEPS sintético"};
  sealed record Ids(Guid ProgramId,Guid MaterialId,Guid ProductId);
}
